"""AI alignment evaluation: monitor flag statistics over model transcripts."""


def _flagged_count(events):
    return sum(1 for event in events if event["flagged"] is True)


def monitor_flag_rate(events):
    """The flag rate of a list of transcripts. See SPEC.md section 1."""
    return _flagged_count(events) / len(events) if events else 0.0


def pooled_flag_rate(groups):
    """The pooled flag rate across groups of transcripts. See SPEC.md section 2."""
    total = sum(len(events) for events in groups.values())
    if not total:
        return 0.0
    return sum(_flagged_count(events) for events in groups.values()) / total


def flags_in_window(daily_counts, days):
    """Sum over a trailing window of daily counts. See SPEC.md section 3."""
    return sum(daily_counts[-days:]) if days > 0 else 0


def flag_rate_by_group(groups):
    """The flag rate of each group. See SPEC.md section 9."""
    return {
        name: monitor_flag_rate(groups[name]) if groups[name] else None
        for name in sorted(groups)
    }


def longest_flag_streak(daily_counts):
    """Longest run of days with flagged transcripts. See SPEC.md section 10."""
    best = current = 0
    for count in daily_counts:
        if count > 0:
            current += 1
            best = max(best, current)
        else:
            current = 0
    return best

"""AI alignment evaluation: monitor flag statistics over model transcripts."""


def parse_transcript_log(lines):
    """Parse log lines into transcripts. See SPEC.md section 4."""
    flag_values = {"1": True, "0": False, "": None}
    out = []
    for line_number, line in enumerate(lines, start=1):
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        fields = [field.strip() for field in line.split(",")]
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected exactly three fields")
        id_, day, flag = fields
        try:
            day = int(day)
        except ValueError as exc:
            raise ValueError(f"line {line_number}: day must be an integer") from exc
        if flag not in flag_values:
            raise ValueError(f"line {line_number}: flagged must be 1, 0, or empty")
        out.append({"id": id_, "day": day, "flagged": flag_values[flag]})
    return out


def dedupe_transcripts(events):
    """Remove duplicate transcripts. See SPEC.md section 5."""
    latest_by_id = {event["id"]: event for event in events}
    return sorted(latest_by_id.values(), key=lambda event: (event["day"], event["id"]))


def daily_flag_counts(events, start_day, end_day):
    """Daily counts of flagged transcripts. See SPEC.md section 6."""
    counts = [0] * (end_day - start_day + 1)
    for event in events:
        day = event["day"]
        if start_day <= day <= end_day and event["flagged"] is True:
            counts[day - start_day] += 1
    return counts

import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5


def test_monitor_flag_rate_counts_none_as_unflagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5


def test_monitor_flag_rate_empty():
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_equal_groups():
    groups = {"a": [{"flagged": True}, {"flagged": False}], "b": [{"flagged": True}, {"flagged": False}]}
    assert pooled_flag_rate(groups) == 0.5


def test_pooled_flag_rate_weights_each_transcript_equally():
    groups = {"small": [{"flagged": True}], "large": [{"flagged": False}] * 3, "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"empty": []}) == 0.0


@pytest.mark.parametrize(("days", "expected"), [(0, 0), (2, 6), (5, 7)])
def test_flags_in_window(days, expected):
    assert flags_in_window([1, 2, 4], days) == expected


def test_parse_transcript_log_one_line():
    assert parse_transcript_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "flagged": True}]


def test_parse_transcript_log_strips_fields_and_skips_blank_lines_and_comments():
    events = parse_transcript_log(["", " \t\n", "# header", "  # comment", " x , 3 , 0 ", " y , 4 , "])
    assert events == [
        {"id": "x", "day": 3, "flagged": False},
        {"id": "y", "day": 4, "flagged": None},
    ]
    assert events[0]["flagged"] is False


@pytest.mark.parametrize("bad_line", ["x,3", "x,3,1,extra", "x,today,1"])
def test_parse_transcript_log_error_counts_skipped_lines(bad_line):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_transcript_log(["# header", " ", "ok,3,1", bad_line])


def test_dedupe_transcripts_keeps_last_record_and_sorts_by_day_then_id():
    first = {"id": "a", "day": 4, "flagged": True}
    last = {"id": "a", "day": 2, "flagged": False}
    same_day = {"id": "b", "day": 2, "flagged": True}
    earlier_day = {"id": "z", "day": 1, "flagged": None}
    assert dedupe_transcripts([first, same_day, earlier_day, last]) == [earlier_day, last, same_day]


def test_daily_flag_counts_includes_empty_days_and_ignores_outside_range():
    events = parse_transcript_log(["a,0,1", "b,1,1", "c,1,1", "d,2,0", "e,2,", "f,4,1", "g,5,1"])
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 4, 1) == []


def test_monitor_summary_basic():
    e = [{"id": "a", "day": 1, "flagged": True}, {"id": "b", "day": 2, "flagged": False}]
    assert monitor_summary({"g": e}, 1) == {"rate": 0.5, "recent": 0, "groups": 1}


def test_monitor_summary_uses_calendar_days_and_nonempty_groups():
    groups = {
        "a": parse_transcript_log(["x,1,1", "y,4,0"]),
        "b": parse_transcript_log(["z,6,"]),
        "empty": [],
    }
    assert monitor_summary(groups, 5) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 6)["recent"] == 1
    assert monitor_summary({"empty": []}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_groups_and_breaks_ties_by_name():
    groups = {
        "z": [{"flagged": False}],
        "b": [{"flagged": True}],
        "a": [{"flagged": True}],
        "empty": [],
    }
    assert top_flagged_groups(groups, 2) == ["a", "b"]
    assert top_flagged_groups(groups, 5) == ["a", "b", "z"]


def test_flag_rate_by_group_sorts_keys_and_distinguishes_empty_groups():
    groups = {"z": [{"flagged": True}], "b": [{"flagged": None}], "a": []}
    assert list(flag_rate_by_group(groups).items()) == [("a", None), ("b", 0.0), ("z", 1.0)]


@pytest.mark.parametrize(("counts", "expected"), [([], 0), ([-1, 0], 0), ([1, -1, 2, 3, 0, 1], 2)])
def test_longest_flag_streak(counts, expected):
    assert longest_flag_streak(counts) == expected
